protected ValueTask FillParameters<TArg>(int start,
											 object?[] args,
											 IServiceProvider serviceProvider,
											 TArg? arg)
	{
		for (var i = start; i < Parameters.Length; i ++)
		{
			var parameter = Parameters[i];

			if (TupleHelper.TryMatch(parameter.MemberType, ref arg, out var value))
			{
				args[i] = value;
			}
			else if (parameter.AsyncValueGetter is { } asyncValueGetter)
			{
				var valueTask = asyncValueGetter(serviceProvider);

				if (!valueTask.IsCompletedSuccessfully)
				{
					return FillParametersWait(valueTask, i, args, serviceProvider, arg);
				}

				args[i] = valueTask.Result;
			}
			else
			{
				var syncValueGetter = parameter.SyncValueGetter;

				Infra.NotNull(syncValueGetter);

				args[i] = syncValueGetter(serviceProvider);
			}
		}

		return ValueTask.CompletedTask;
	}

private async ValueTask FillParametersWait<TArg>(ValueTask<object?> valueTask,
													 int index,
													 object?[] args,
													 IServiceProvider serviceProvider,
													 TArg? arg)
	{
		args[index] = await valueTask.ConfigureAwait(false);

		await FillParameters(index + 1, args, serviceProvider, arg).ConfigureAwait(false);
	}

protected ValueTask SetRequiredMembers<TArg>(int start,
												 object service,
												 IServiceProvider serviceProvider,
												 TArg? arg)
	{
		for (var i = start; i < RequiredMembers.Length; i ++)
		{
			var requiredMember = RequiredMembers[i];

			var setter = requiredMember.MemberSetter;
			Infra.NotNull(setter);

			if (TupleHelper.TryMatch(requiredMember.MemberType, ref arg, out var value))
			{
				setter(service, value);
			}
			else if (requiredMember.AsyncValueGetter is { } asyncValueGetter)
			{
				var valueTask = asyncValueGetter(serviceProvider);

				if (!valueTask.IsCompletedSuccessfully)
				{
					return SetRequiredMembersWait(valueTask, i, service, serviceProvider, arg);
				}

				setter(service, valueTask.Result);
			}
			else
			{
				var syncValueGetter = requiredMember.SyncValueGetter;

				Infra.NotNull(syncValueGetter);

				setter(service, syncValueGetter(serviceProvider));
			}
		}

		return ValueTask.CompletedTask;
	}

private async ValueTask SetRequiredMembersWait<TArg>(ValueTask<object?> valueTask,
														 int index,
														 object service,
														 IServiceProvider serviceProvider,
														 TArg? arg)
	{
		RequiredMembers[index].MemberSetter!(service, await valueTask.ConfigureAwait(false));

		await SetRequiredMembers(index + 1, service, serviceProvider, arg).ConfigureAwait(false);
	}

private ValueTask<TService> GetService<TArg>(IServiceProvider serviceProvider, TArg? arg)
	{
		var valueTask = CreateInstance(serviceProvider, arg);

		if (RequiredMembers.Length == 0)
		{
			return valueTask;
		}

		if (valueTask.IsCompletedSuccessfully)
		{
			return PostCreateInstance(valueTask.Result, serviceProvider, arg);
		}

		return GetServiceWait(valueTask, serviceProvider, arg);
	}

private async ValueTask<TService> GetServiceWait<TArg>(ValueTask<TService> valueTask, IServiceProvider serviceProvider, TArg? arg)
	{
		var service = await valueTask.ConfigureAwait(false);

		return await PostCreateInstance(service, serviceProvider, arg).ConfigureAwait(false);
	}

private ValueTask<TService> CreateInstance<TArg>(IServiceProvider serviceProvider, TArg? arg)
	{
		if (Parameters.Length == 0)
		{
			try
			{
				return _factory([]);
			}
			catch (Exception ex)
			{
				return ValueTask.FromException<TService>(GetFactoryException(ex));
			}
		}

		var args = RentArray();
		ValueTask valueTask;

		try
		{
			valueTask = FillParameters(start: 0, args, serviceProvider, arg);

			if (valueTask.IsCompletedSuccessfully)
			{
				var service = _factory(args);
				ReturnArray(args);

				return service;
			}
		}
		catch (Exception ex)
		{
			ReturnArray(args);

			return ValueTask.FromException<TService>(GetFactoryException(ex));
		}

		return CreateInstanceWait(valueTask, args);
	}

private async ValueTask<TService> CreateInstanceWait(ValueTask valueTask, object?[] args)
	{
		try
		{
			await valueTask.ConfigureAwait(false);

			return await _factory(args).ConfigureAwait(false);
		}
		catch (Exception ex)
		{
			throw GetFactoryException(ex);
		}
		finally
		{
			ReturnArray(args);
		}
	}

private ValueTask<TService> PostCreateInstance<TArg>(TService service, IServiceProvider serviceProvider, TArg? arg)
	{
		ValueTask valueTask;

		try
		{
			valueTask = SetRequiredMembers(start: 0, service!, serviceProvider, arg);

			if (valueTask.IsCompletedSuccessfully)
			{
				return new ValueTask<TService>(service);
			}
		}
		catch (Exception ex)
		{
			return ValueTask.FromException<TService>(GetFactoryException(ex));
		}

		return PostCreateInstanceWait(valueTask, service);
	}

private async ValueTask<TService> PostCreateInstanceWait(ValueTask valueTask, TService service)
	{
		try
		{
			await valueTask.ConfigureAwait(false);

			return service;
		}
		catch (Exception ex)
		{
			throw GetFactoryException(ex);
		}
	}

