public string ToString(string? format, IFormatProvider? formatProvider)
	{
		if (_type is null)
		{
			return string.Empty;
		}

		if (format?.Split('|') is not [var dlm, var arg] || !TryGetArgFormat(arg, out var argFormat, out var index))
		{
			return _type.FriendlyName;
		}

		var sb = new StringBuilder();

		string? delimiter = null;

		foreach (var type in _type.DecomposeType())
		{
			if (delimiter is not null)
			{
				sb.Append(delimiter);
			}
			else
			{
				delimiter = dlm;
			}

			sb.AppendFriendlyName(type).Append(' ').AppendFormat(formatProvider, argFormat, index ++);
		}

		return sb.ToString();
	}

private static bool TryGetArgFormat(string arg, [MaybeNullWhen(false)] out string argFormat, out int index)
	{
		index = 0;
		argFormat = null;

		if (string.IsNullOrEmpty(arg) || arg[0] is '0' or '1')
		{
			return false;
		}

		var digits = 0;
		var badChars = 0;

		foreach (var ch in arg)
		{
			if (ch is '0' or '1')
			{
				digits ++;
			}
			else if (!char.IsLetter(ch) && ch != '_')
			{
				badChars ++;
			}
		}

		if (badChars > 0 || digits > 1)
		{
			return false;
		}

		if (digits == 0)
		{
			argFormat = arg;

			return true;
		}

		var sb = new StringBuilder(arg.Length + 2);

		foreach (var ch in arg)
		{
			if (ch is '0' or '1')
			{
				index = ch - '0';
				sb.Append(@"{0}");
			}
			else
			{
				sb.Append(ch);
			}
		}

		argFormat = sb.ToString();

		return true;
	}

