public IServiceProviderDataActions? Event(ActionsEventType type, ref ActionsContext context)
	{
		switch (type)
		{
			case ActionsEventType.ServiceRequesting:
				var logger = GetLogger();
				context.UserDataObject = logger;

				logger.ServiceRequesting(context.TypeKey);

				break;

			case ActionsEventType.ServiceRequested:
				((ServiceLogger)context.UserDataObject!).ServiceRequested();

				break;

			case ActionsEventType.ServiceRequestError:
				((ServiceLogger)context.UserDataObject!).ServiceRequestError();

				break;

			case ActionsEventType.FactoryCalling:
				var stat = GetStat(context.TypeKey);
				context.UserDataObject = stat;
				stat.FactoryCalling();

				GetLogger().FactoryCalling(stat.CallsCount);

				break;

			case ActionsEventType.FactoryCalled:
				((Stat)context.UserDataObject!).FactoryCalled();

				break;
			case ActionsEventType.FactoryCallError:
				((Stat)context.UserDataObject!).FactoryCallError();

				break;

			case ActionsEventType.ServiceRequest:
			case ActionsEventType.FactoryCall:
			case ActionsEventType.Enter:
			case ActionsEventType.Exit:
			case ActionsEventType.Error:
			case ActionsEventType.SyncExit:
			case ActionsEventType.ServiceRequestRunning:
			case ActionsEventType.FactoryCallRunning:

			default:
				break;
		}

		return null;
	}

public void RegisterService(ServiceEntry serviceEntry)
	{
		_writer.Write(@"REG: ");

		var scope = serviceEntry.InstanceScope.ToString();
		_writer.Write(scope);

		for (var i = 0; i < 18 - scope.Length; i ++)
		{
			_writer.Write(' ');
		}

		_writer.Write(@" | ");
		_writer.WriteLine(serviceEntry.Key.ToString());
	}

private bool TryOwnWriter()
	{
		// Fast-fail check to avoid unnecessary Interlocked operation if already owned
		if (_writerOwned != 0)
		{
			return false;
		}

		return Interlocked.CompareExchange(ref _writerOwned, value: 1, comparand: 0) == 0;
	}

private void ReleaseWriter()
	{
		DumpLoggersQueue();

		_writerOwned = 0;
	}

private void DumpStatistics()
	{
		var maxServiceLength = _stats.Max(p => p.Value.ServiceName.Length);

		var list = from pair in _stats
				   let nc = (pair.Value.ServiceName, pair.Value.CallsCount)
				   orderby nc.CallsCount descending, nc.ServiceName
				   select nc;

		foreach (var (serviceName, callsCount) in list)
		{
			_writer.Write(@"STAT: ");
			_writer.Write(serviceName);

			for (var i = 0; i < maxServiceLength - serviceName.Length; i ++)
			{
				_writer.Write(' ');
			}

			_writer.Write(@" | ");
			_writer.Write(callsCount.ToString());
			_writer.WriteLine(callsCount > 1 ? @" calls" : @" call");
		}
	}

protected virtual void Dispose(bool disposing)
	{
		if (disposing)
		{
			try
			{
				DumpLoggersQueue();

				DumpStatistics();

				_writer.Flush();

				if (!leaveOpen)
				{
					_writer.Close();
				}
			}
			catch (ObjectDisposedException)
			{
				// ignore
			}
		}
	}

private void DumpLoggersQueue()
	{
		while (_loggersToDump.TryDequeue(out var logger))
		{
			logger.DumpLocalWriter();
		}
	}

[MethodImpl(MethodImplOptions.Synchronized)]
		public void ServiceRequesting(TypeKey typeKey)
		{
			_level ++;

			if (_factoryCalled)
			{
				Writer.WriteLine();

				_factoryCalled = false;
			}

			WriteIdent();

			Writer.Write(typeKey.ToString());

			_noFactory = true;
		}

[MethodImpl(MethodImplOptions.Synchronized)]
		public void FactoryCalling(int callsCount)
		{
			Writer.Write($@" {{#{callsCount}}}");

			_factoryCalled = true;
			_noFactory = false;
		}

[MethodImpl(MethodImplOptions.Synchronized)]
		public void ServiceRequestError()
		{
			Writer.Write(@" (ERROR)");

			ServiceRequested();
		}

[MethodImpl(MethodImplOptions.Synchronized)]
		public void ServiceRequested()
		{
			if (_noFactory)
			{
				Writer.WriteLine(@" {CACHED}");
			}
			else
			{
				if (_factoryCalled)
				{
					Writer.WriteLine();
					_factoryCalled = false;
				}
				else
				{
					WriteIdent();
					Writer.WriteLine(@"__");
				}
			}

			_noFactory = false;

			if (-- _level == 0 && _parentWriterOwner)
			{
				parent.ReleaseWriter();

				_parentWriterOwner = false;
			}
		}

private void WriteIdent()
		{
			var padding = false;

			for (var i = 1; i < _level; i ++)
			{
				WriteWithPadding(@"|");
			}

			WriteWithPadding(_level < _previousLevel ? @"\" : @">> ");

			_previousLevel = _level;

			return;

			void WriteWithPadding(string str)
			{
				if (padding)
				{
					Writer.Write(@"  ");
				}

				padding = true;
				Writer.Write(str);
			}
		}

private bool TryGetParentWriterOwnership()
		{
			if (_parentWriterOwner)
			{
				return true;
			}

			if (!parent.TryOwnWriter())
			{
				return false;
			}

			_parentWriterOwner = true;

			DumpLocalWriter();

			return true;
		}

[MethodImpl(MethodImplOptions.Synchronized)]
		public void DumpLocalWriter()
		{
			if (_localWriter is not { } localWriter)
			{
				return;
			}

			parent._writer.Write(localWriter.GetStringBuilder());

			localWriter.Close();

			_localWriter = null;
		}

public void FactoryCalling()
		{
			CallsCount ++;

			if (++ _deepLevel > 500)
			{
				throw new DependencyInjectionException(Resources.Exception_CycleReferenceDetectedInContainerConfiguration);
			}
		}

