private static async ValueTask<string[]> GetList<T>(IAsyncEnumerable<T> asyncEnumerable)
	{
		var list = new List<string>();

		await foreach (var svc in asyncEnumerable)
		{
			list.Add(((ISomeValue)svc!).Value);
		}

		return [.. list];
	}

