		var asyncDebug1 = AsyncDebug(debugger);
		var asyncDebug2 = AsyncDebug(debugger);
		var asyncDebug3 = AsyncDebug(debugger);

		await asyncDebug1;
		await asyncDebug2;
		await asyncDebug3;

