public static int Count<T>(this IAsyncEnumerable<T> en)
	{
		return InternalCount().Result;

		async Task<int> InternalCount()
		{
			var count = 0;

			await foreach (var _ in en)
			{
				count ++;
			}

			return count;
		}
	}

